package raft

import("bytes";"encoding/json";"errors";"fmt";"io";"net/http";"sync";"time")
type HTTPTransport struct{self string;addrs map[string]string;client *http.Client;mu sync.RWMutex;blocked map[string]bool;delay time.Duration}
func NewHTTPTransport(self string,addrs map[string]string)*HTTPTransport{return &HTTPTransport{self:self,addrs:addrs,blocked:map[string]bool{},client:&http.Client{Timeout:500*time.Millisecond}}}
func(t *HTTPTransport)Addr(id string)string{return t.addrs[id]}
func(t *HTTPTransport)Call(peer,method string,args,reply any)error{t.mu.RLock();blocked,delay:=t.blocked[peer],t.delay;t.mu.RUnlock();if blocked{return errors.New("fault injection: link blocked")};if delay>0{time.Sleep(delay)};addr,ok:=t.addrs[peer];if !ok{return fmt.Errorf("unknown peer %q",peer)};body,e:=json.Marshal(args);if e!=nil{return e};req,e:=http.NewRequest(http.MethodPost,"http://"+addr+"/raft/"+method,bytes.NewReader(body));if e!=nil{return e};req.Header.Set("X-Raft-From",t.self);resp,e:=t.client.Do(req);if e!=nil{return e};defer resp.Body.Close();if resp.StatusCode!=200{_,_=io.Copy(io.Discard,resp.Body);return fmt.Errorf("peer %s: status %d",peer,resp.StatusCode)};return json.NewDecoder(resp.Body).Decode(reply)}
func(t *HTTPTransport)SetFault(blocked []string,delay time.Duration){t.mu.Lock();defer t.mu.Unlock();t.blocked=map[string]bool{};for _,b:=range blocked{t.blocked[b]=true};t.delay=delay}
func(t *HTTPTransport)inboundBlocked(r *http.Request)bool{t.mu.RLock();defer t.mu.RUnlock();return t.blocked[r.Header.Get("X-Raft-From")]}
type faultBody struct{Blocked []string `json:"blocked"`;DelayMs int `json:"delay_ms"`}
func(t *HTTPTransport)Handler(n *Node)http.Handler{mux:=http.NewServeMux();write:=func(w http.ResponseWriter,v any){w.Header().Set("Content-Type","application/json");_=json.NewEncoder(w).Encode(v)};mux.HandleFunc("POST /raft/RequestVote",func(w http.ResponseWriter,r *http.Request){if t.inboundBlocked(r){http.Error(w,"blocked",503);return};var a RequestVoteArgs;if e:=json.NewDecoder(r.Body).Decode(&a);e!=nil{http.Error(w,e.Error(),400);return};write(w,n.HandleRequestVote(&a))});mux.HandleFunc("POST /raft/AppendEntries",func(w http.ResponseWriter,r *http.Request){if t.inboundBlocked(r){http.Error(w,"blocked",503);return};var a AppendEntriesArgs;if e:=json.NewDecoder(r.Body).Decode(&a);e!=nil{http.Error(w,e.Error(),400);return};write(w,n.HandleAppendEntries(&a))});mux.HandleFunc("GET /raft/status",func(w http.ResponseWriter,r *http.Request){write(w,n.Status())});mux.HandleFunc("POST /raft/fault",func(w http.ResponseWriter,r *http.Request){var f faultBody;if e:=json.NewDecoder(r.Body).Decode(&f);e!=nil{http.Error(w,e.Error(),400);return};t.SetFault(f.Blocked,time.Duration(f.DelayMs)*time.Millisecond);write(w,f)});return mux}
